package dev.gnaspham1218.maifit.backend.workout.dto;

import dev.gnaspham1218.maifit.backend.workout.entity.WorkoutExercise;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;
import java.util.UUID;

// Same limits as the DB CHECK constraints; the cross-field rules (pace, time window, daily
// limits) are checked in WorkoutService.
// clientId: generated by the browser once per set, so sending the same set twice saves it once.
public record CreateWorkoutRequest(
        @NotNull WorkoutExercise exercise,
        @NotNull @Min(1) @Max(500) Integer reps,
        @NotNull Instant startedAt,
        @NotNull @Min(5) @Max(3600) Integer durationSec,
        @NotNull UUID clientId
) {
}
